public sealed record ScoringPolicy(int PassMark, bool AllowLate, DateTimeOffset? ClosesAt);

public ScoringPolicy FreezeForSubmit(ScoringPolicy live, DateTimeOffset utc)
    => live with
    {
        AllowLate = false,
        ClosesAt = utc
    };

// live is unchanged; workers receive frozen.

public sealed record LtiConsumer(string Issuer, List<string> Audiences);

public LtiConsumer GrantAudience(LtiConsumer consumer, string audience)
    => consumer with
    {
        Audiences = [.. consumer.Audiences, audience]
    };

public sealed record AttemptState(string Status, int Score, bool Submitted);

public AttemptState OnScore(AttemptState state, int newScore) => state switch
{
    { Submitted: true } => state,
    { Score: < 0 } => throw new InvalidOperationException("Cannot score unsubmitted attempt with negative placeholder."),
    _ => state with { Score = newScore }
};

public sealed record AuthDecision(string UserId, IReadOnlyList<string> Roles, bool Allowed);

public AuthDecision GrantRole(AuthDecision live, string role)
{
    // Snapshot for worker — original unchanged
    var snapshot = live with { Allowed = true };

    // TRAP: Roles list still shared if live.Roles is mutable List
    // FIX: snapshot = live with { Roles = live.Roles.Append(role).ToImmutableArray() };
    return snapshot;
}
